# 方式一：CLI 命令（推荐）\nclaude mcp add --trans:
# 방법 1: CLI 명령(권장)
claude mcp add --transport http android-log-analyzer http://127.0.0.1:{0}/mcp

# 방법 2: ~/.claude.json 또는 프로젝트 루트의 .mcp.json 편집
{
  "mcpServers": {
    "android-log-analyzer": {
      "type": "streamable-http",
      "url": "http://127.0.0.1:{1}/mcp"
    }
  }
}
